<?php
require __DIR__.'/../config/config.php';
if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$cid=(int)($_GET['conversation_id']??0);if(!$cid){http_response_code(400);exit('Invalid conversation.');}
$q=$pdo->prepare('SELECT u.id,u.username,u.full_name FROM conversation_members cm JOIN users u ON u.id=cm.user_id WHERE cm.conversation_id=? ORDER BY cm.user_id');$q->execute([$cid]);$members=$q->fetchAll();if(count($members)!==2){http_response_code(404);exit('Conversation not found.');}
$log=$pdo->prepare('INSERT INTO admin_audit_logs(admin_id,action,conversation_id,created_at) VALUES(?,?,?,NOW())');$log->execute([$_SESSION['admin_id'],'view_conversation',$cid]);
$s=$pdo->prepare('SELECT a.id,a.body,a.sent_at,u.username,u.full_name FROM admin_message_archive a JOIN users u ON u.id=a.sender_id WHERE a.conversation_id=? ORDER BY a.id ASC LIMIT 2000');$s->execute([$cid]);$messages=$s->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/css/app.css"><title>Conversation · RAAZ Admin</title></head><body><header class="top"><a class="logo" href="index.php">RAAZ<span>.</span> ADMIN</a><a href="index.php">Dashboard</a></header><main class="admin"><p class="sub"><a href="user-chats.php?user_id=<?=(int)$members[0]['id']?>">Back to conversations</a></p><h1>Conversation #<?=$cid?></h1><p class="sub"><?=e($members[0]['full_name'])?> (@<?=e($members[0]['username'])?>) ↔ <?=e($members[1]['full_name'])?> (@<?=e($members[1]['username'])?>)</p><div class="notice">Restricted moderation view. This page displays messages retained in the archive, including messages that have expired from users' chat screens. Viewing is audit-logged.</div><div class="admin-chat"><?php if(!$messages):?><p class="sub">No archived messages are available for this conversation. Messages sent before archive installation may not be present.</p><?php else:foreach($messages as $m):?><article class="admin-message"><div class="admin-message-head"><strong><?=e($m['full_name'])?> <small>@<?=e($m['username'])?></small></strong><time><?=e($m['sent_at'])?></time></div><p><?=nl2br(e($m['body']))?></p></article><?php endforeach;endif?></div></main></body></html>
